import React from 'react';
import {AbsoluteFill,Fondo,Rotulo,Etiqueta,Contador,Ondas,Destello,Impacto,Camara,Carita,useS,en,clamp,interpolate,Easing,FONT} from './kit';
const INICIO=en('piel');
const FRIO=en('frío');
const DENTRO=en('entramos');
const RAIZ=en('raíz');
const MUSCULO=en('músculo');
const CONTRAE=en('contrae');
const MAMIFEROS=en('mamíferos');
const HUMANOS=en('humanos');
const MUSICA=en('música');
const FINAL=en('Envíaselo');
const ROSA='#ff8fb1', AZUL='#9fe3ff', AMARILLO='#ffd84d';
const lerp=(s:number,a:number,b:number)=>interpolate(s,[a,b],[0,1],clamp);
const Vello:React.FC<{s:number;x:number;idx:number}> = ({s,x,idx})=>{
 const tension=lerp(s,CONTRAE,CONTRAE+0.5);
 const frio=lerp(s,FRIO,FRIO+0.5);
 const y=1110+((idx%3)-1)*34;
 const ang=(idx%2?1:-1)*(12+48*Math.max(frio,tension));
 return <g transform={'translate('+x+' '+y+')'}>
   <path d="M -55 130 Q 0 80 55 130" stroke="#ffb4c4" strokeWidth={20} fill="none"/>
   <path d="M 0 90 Q 15 -130 45 -280" stroke={AZUL} strokeWidth={11} fill="none"
     transform={'rotate('+ang+' 0 90)'}/>
   <circle cx={0} cy={90} r={11} fill={AMARILLO}/>
 </g>;
};
const Piel:React.FC<{s:number}> = ({s})=>{
 const interno=lerp(s,DENTRO-0.3,DENTRO+0.8);
 const tiron=lerp(s,CONTRAE,CONTRAE+0.45);
 return <AbsoluteFill>
  <svg viewBox="0 0 1080 1920" width="1080" height="1920">
   <rect x="0" y="975" width="1080" height="945" fill="#4f235d"/>
   <path d="M 0 990 Q 180 970 330 990 T 660 990 T 1080 990 L 1080 1170 L 0 1170 Z" fill="#ffabbd"/>
   <rect x="0" y="1170" width="1080" height="750" fill="#bb627f"/>
   {[170,360,560,770,940].map((x,i)=><Vello key={i} s={s} x={x} idx={i}/>)}
   <g opacity={interno}>
    <path d="M 550 1020 L 565 1520" stroke="#ffe3b2" strokeWidth={46} strokeLinecap="round"/>
    <ellipse cx="570" cy="1450" rx="65" ry="135" fill="#873b62" stroke={ROSA} strokeWidth={14}/>
    <path d="M 565 1450 L 750 1230" stroke="#ffd84d" strokeWidth={30} strokeLinecap="round"
      transform={'translate('+(-45*tiron)+' '+(65*tiron)+')'}/>
    <circle cx="740" cy="1240" r="34" fill={AMARILLO}/>
    <circle cx="725" cy="1230" r="5" fill="#301538"/>
    <circle cx="748" cy="1230" r="5" fill="#301538"/>
    <path d="M 725 1251 Q 739 1264 752 1251" stroke="#301538" strokeWidth={5} fill="none"/>
    {[0,1,2,3,4,5,6,7].map(i=><circle key={i} cx={350+i*63} cy={1550+Math.sin(i+s*2)*30}
       r={8+i%3*4} fill={AZUL} opacity={0.3+0.5*interno}/>)}
   </g>
  </svg>
  {interno>0.2 && <Etiqueta texto="músculo erector" x={815} y={850} px={748} py={1230} t0={MUSCULO} size={27} color={AMARILLO}/>}
 </AbsoluteFill>;
};
const Comparacion:React.FC<{s:number}> = ({s})=>{
 const p=lerp(s,MAMIFEROS,MAMIFEROS+0.5), q=lerp(s,HUMANOS,HUMANOS+0.5);
 return <AbsoluteFill style={{opacity:p}}>
  <svg viewBox="0 0 1080 1920" width="1080" height="1920">
   <rect x="45" y="710" width="460" height="760" rx="65" fill="#39294a" stroke={AMARILLO} strokeWidth={8}/>
   <rect x="575" y="710" width="460" height="760" rx="65" fill="#39294a" stroke={AZUL} strokeWidth={8}/>
   {Array.from({length:45}).map((_,i)=><path key={i} d={'M '+(85+(i%9)*48)+' '+(850+Math.floor(i/9)*115)+' q -45 -70 -20 -100'} stroke={AMARILLO} strokeWidth={11} fill="none"/>)}
   {Array.from({length:9}).map((_,i)=><path key={i} d={'M '+(620+(i%3)*130)+' '+(920+Math.floor(i/3)*150)+' q 5 -35 13 -85'} stroke={AZUL} strokeWidth={8} fill="none" opacity={q}/>)}
  </svg>
  <div style={{position:'absolute',top:570,left:140,fontFamily:FONT,color:AMARILLO,fontSize:50}}>PELAJE</div>
  <div style={{position:'absolute',top:570,left:625,fontFamily:FONT,color:AZUL,fontSize:50}}>HUMANOS</div>
 </AbsoluteFill>;
};
export const Escena:React.FC=()=>{
 const {s,lin}=useS();
 const comp=lerp(s,MAMIFEROS-0.3,MAMIFEROS+0.3)*(1-lerp(s,MUSICA-0.3,MUSICA+0.2));
 const fin=lerp(s,MUSICA-0.25,MUSICA+0.45);
 return <AbsoluteFill>
  <Fondo colores={['#4b2380','#211345','#0b0620']} particulas={AZUL}/>
  <AbsoluteFill style={{opacity:1-comp}}>
   <Camara centroY={1080} paradas={[
    {t:0,x:540,y:1080,zoom:1},
    {t:DENTRO-0.25,x:550,y:1120,zoom:1.2},
    {t:RAIZ,x:560,y:1300,zoom:3.8},
    {t:MUSCULO,x:650,y:1320,zoom:2.6},
    {t:CONTRAE+0.5,x:620,y:1200,zoom:2.1},
    {t:MAMIFEROS-0.35,x:540,y:1080,zoom:1},
    {t:MUSICA,x:540,y:1080,zoom:1},
    {t:FINAL,x:540,y:1080,zoom:1}
   ]}><Piel s={s}/></Camara>
  </AbsoluteFill>
  {comp>0 && <Comparacion s={s}/>}
  {s>=CONTRAE && s<CONTRAE+1 && <Destello t0={CONTRAE}/>}
  {s>=FRIO && s<FRIO+2 && <Ondas x={540} y={970} t0={FRIO}/>}
  {s>=MUSICA && <div style={{position:'absolute',top:500,left:400,fontSize:110,opacity:fin,color:AMARILLO}}>♫ ♪</div>}
  <Rotulo items={[[0,DENTRO,'tu piel por fuera'],[DENTRO,MAMIFEROS,'dentro de tu piel'],[MAMIFEROS,MUSICA,'el pelaje'],[MUSICA,999,'tu piel otra vez']]}/>
 </AbsoluteFill>;
};
